// ── Parse AI Score Response ───────────────────────────────
// Safely parses the AI JSON response and merges with lead data.
// Handles malformed AI output with fallback defaults.

const aiResp = $input.first().json;
const leadData = $('🔀 Merge Paths → Pre-AI').item.json;

// Extract AI message content
const rawContent = aiResp.choices?.[0]?.message?.content
  || aiResp.message?.content
  || '{}';

let aiResult = {};
try {
  // Strip any accidental markdown fences
  const cleaned = rawContent.replace(/```json|```/g, '').trim();
  aiResult = JSON.parse(cleaned);
} catch(e) {
  // Fallback: extract score with regex if JSON parse fails
  const scoreMatch = rawContent.match(/"score"\s*:\s*(\d+)/);
  const tierMatch  = rawContent.match(/"tier"\s*:\s*"([^"]+)"/);
  aiResult = {
    score:             scoreMatch ? parseInt(scoreMatch[1]) : 5,
    tier:              tierMatch  ? tierMatch[1] : 'Warm',
    reasoning:         'AI response parsing failed — default score assigned.',
    topStrength:       'Unknown',
    topWeakness:       'Could not parse AI response',
    recommendedAction: 'Manual review recommended',
  };
}

// Validate score range
const score = Math.min(10, Math.max(1, parseInt(aiResult.score) || 5));
const tier  = ['Hot','Warm','Cold'].includes(aiResult.tier) ? aiResult.tier : (
  score >= 8 ? 'Hot' : score >= 5 ? 'Warm' : 'Cold'
);

return [{
  json: {
    ...leadData,
    aiScore:           score,
    aiTier:            tier,
    aiReasoning:       aiResult.reasoning       || '',
    topStrength:       aiResult.topStrength      || '',
    topWeakness:       aiResult.topWeakness      || '',
    recommendedAction: aiResult.recommendedAction|| '',
    scoredAt:          new Date().toISOString(),
    scoreSource:       'gpt-4o-mini',
  }
}];

// ── Batch Summary Aggregator ──────────────────────────────
// Collects all processed leads and computes batch statistics.
// Runs after ALL individual leads have been processed.

const allItems = $input.all();

let totalLeads  = 0;
let hotLeads    = 0;
let warmLeads   = 0;
let coldLeads   = 0;
let withEmail   = 0;
let withWebsite = 0;
let scoreSum    = 0;
let highScores  = [];  // score >= 7

for (const item of allItems) {
  const d = item.json;
  totalLeads++;
  scoreSum += (d.aiScore || 0);
  if (d.aiTier === 'Hot')  hotLeads++;
  if (d.aiTier === 'Warm') warmLeads++;
  if (d.aiTier === 'Cold') coldLeads++;
  if (d.emailExtracted)   withEmail++;
  if (d.hasWebsite)       withWebsite++;
  if ((d.aiScore || 0) >= 7) {
    highScores.push({
      name:  d.name,
      score: d.aiScore,
      tier:  d.aiTier,
      email: d.email || 'N/A',
      phone: d.phone || 'N/A',
      action: d.recommendedAction || '',
    });
  }
}

// Sort high scores descending
highScores.sort((a,b) => b.score - a.score);
const avgScore = totalLeads > 0 ? (scoreSum / totalLeads).toFixed(1) : 0;

// Get batch metadata from first item
const meta = allItems[0]?.json || {};

return [{
  json: {
    batchId:      meta.batchId      || 'unknown',
    searchQuery:  meta.ourCompany?.name || 'Unknown',
    totalLeads,
    hotLeads,
    warmLeads,
    coldLeads,
    withEmail,
    withWebsite,
    avgScore,
    highScoreLeads: highScores.slice(0, 5),  // top 5 only
    completedAt:  new Date().toISOString(),
  }
}];

// ── Build Telegram Notification Message ──────────────────
// Constructs a rich, Markdown-formatted Telegram message
// summarising the completed batch processing run.

const s = $input.first().json;

const topLeadsText = s.highScoreLeads.map((lead, i) =>
  `  ${i+1}. *${lead.name}* — Score: ${lead.score}/10 (${lead.tier})\n` +
  `     📧 ${lead.email} | 📞 ${lead.phone}\n` +
  `     ➡️ ${lead.action}`
).join('\n\n');

const completedTime = new Date(s.completedAt).toLocaleString('en-US', {
  timeZone: 'America/New_York',
  dateStyle: 'medium',
  timeStyle: 'short',
});

const message = [
  `🎯 *Sales Lead Batch Complete*`,
  ``,
  `📦 *Batch ID:* \`${s.batchId}\``,
  `⏰ *Completed:* ${completedTime}`,
  ``,
  `📊 *Results Summary*`,
  `┌─────────────────────────┐`,
  `│ Total Leads:    ${String(s.totalLeads).padStart(4,' ')} │`,
  `│ 🔥 Hot (8-10):  ${String(s.hotLeads).padStart(4,' ')} │`,
  `│ 🟡 Warm (5-7):  ${String(s.warmLeads).padStart(4,' ')} │`,
  `│ 🔵 Cold (1-4):  ${String(s.coldLeads).padStart(4,' ')} │`,
  `│ 📧 With Email:  ${String(s.withEmail).padStart(4,' ')} │`,
  `│ 🌐 With Website:${String(s.withWebsite).padStart(4,' ')} │`,
  `│ ⭐ Avg Score:   ${String(s.avgScore).padStart(4,' ')} │`,
  `└─────────────────────────┘`,
  ``,
  s.highScoreLeads.length > 0 ? `🏆 *Top ${s.highScoreLeads.length} Leads*` : '',
  s.highScoreLeads.length > 0 ? topLeadsText : 'No high-score leads found.',
  ``,
  `✅ All leads logged to Google Sheets.`,
  `👉 Review: https://docs.google.com/spreadsheets/d/${process.env.GOOGLE_SHEET_ID || 'YOUR_SHEET_ID'}`,
].join('\n');

return [{
  json: {
    ...s,
    telegramMessage: message,
  }
}];

const err = $input.first().json;
const msg = (err.execution?.error?.message || '').toLowerCase();
const node = err.execution?.lastNodeExecuted || 'unknown';

let errorType = 'GENERAL_ERROR', severity = 'HIGH', fix = 'Check n8n execution logs.';

if (msg.includes('over_query_limit') || msg.includes('quota')) {
  errorType = 'GOOGLE_API_QUOTA'; severity = 'HIGH';
  fix = 'Google Places API quota exceeded. Wait 24h or upgrade Google Cloud billing plan.';
} else if (msg.includes('request_denied') || msg.includes('invalid_request')) {
  errorType = 'GOOGLE_API_KEY_INVALID'; severity = 'CRITICAL';
  fix = 'Check GOOGLE_PLACES_API_KEY. Ensure Places API is enabled in Google Cloud Console.';
} else if (msg.includes('no places found')) {
  errorType = 'ZERO_RESULTS'; severity = 'LOW';
  fix = 'Search returned no results. Try broader query or different location.';
} else if (node.includes('AI') || node.includes('Score')) {
  errorType = 'AI_SCORING_FAILURE'; severity = 'MEDIUM';
  fix = 'OpenAI API error. Check OPENAI_API_KEY and account balance.';
} else if (node.includes('Sheets')) {
  errorType = 'SHEETS_WRITE_FAILURE'; severity = 'MEDIUM';
  fix = 'Google Sheets write failed. Check OAuth credentials and GOOGLE_SHEET_ID.';
} else if (node.includes('Telegram')) {
  errorType = 'NOTIFICATION_FAILURE'; severity = 'LOW';
  fix = 'Telegram notification failed. Check bot token and TELEGRAM_CHAT_ID. Leads are already saved.';
} else if (msg.includes('timeout')) {
  errorType = 'NETWORK_TIMEOUT'; severity = 'MEDIUM';
  fix = 'HTTP timeout. Service temporarily unavailable. Will retry on next scheduled run.';
}

return [{
  json: {
    timestamp: new Date().toISOString(),
    executionId: err.execution?.id || 'unknown',
    workflowName: err.workflow?.name || 'Sales Automation',
    failedNode: node,
    errorType, errorMessage: err.execution?.error?.message || 'Unknown',
    severity, fix, retryable: severity !== 'CRITICAL',
  }
}];
